const stage = String(msg.topic).split('/')[2];
const t0 = Date.now();
const redis = context.get('redisClient');
const d = context.get('diagSig');
try {
    if (stage === 'redis') {
        await redis.hgetall('diag:absent');
    } else if (stage === 'redis-set') {
        await redis.set('diag:nx:' + Date.now() + ':' + Math.random(), 'x', 'PX', 2000, 'NX');
    } else if (stage === 'verify') {
        // Meme travail cryptographique que le chemin HIT : 2 verifications Ed25519 (JWT + preuve).
        nacl.sign.detached.verify(d.message, d.signature, d.publicKey);
        nacl.sign.detached.verify(d.message, d.signature, d.publicKey);
    } else if (stage === 'verify1') {
        nacl.sign.detached.verify(d.message, d.signature, d.publicKey);
    } else if (stage === 'verify-native') {
        // Alternative : Ed25519 natif de Node (OpenSSL) au lieu de tweetnacl (JS pur).
        crypto.verify(null, d.message, d.nativeKey, d.signature);
        crypto.verify(null, d.message, d.nativeKey, d.signature);
    } else if (stage === 'sha256') {
        crypto.createHash('sha256').update('x'.repeat(200), 'utf8').digest('base64url');
    } // stage === 'echo' : rien, mesure du seul transport MQTT via Node-RED
} catch (e) {
    node.warn('[diag] ' + stage + ' : ' + e.message);
}
const nodeMs = (Date.now() - t0);
msg.topic = 'iot/diag/' + stage + '/response';
msg.payload = { stage: stage, node_ms: nodeMs };
return msg;

