const client = new Redis({
    host: 'host.docker.internal',
    port: 6379,
    username: env.get('REDIS_GATEWAY_USERNAME') || undefined,
    password: env.get('REDIS_GATEWAY_PASSWORD') || undefined,
    lazyConnect: false,
    retryStrategy: (times) => Math.min(times * 100, 3000)
});
client.on('error', (err) => node.warn('[diag] Redis error: ' + err.message));
context.set('redisClient', client);
const kp = nacl.sign.keyPair();
const message = Buffer.from('d'.repeat(200), 'utf8');
const spki = Buffer.concat([Buffer.from('302a300506032b6570032100', 'hex'), Buffer.from(kp.publicKey)]);
context.set('diagSig', {
    nativeKey: crypto.createPublicKey({ key: spki, format: 'der', type: 'spki' }),
    publicKey: kp.publicKey,
    message: message,
    signature: nacl.sign.detached(message, kp.secretKey)
});
